"use client";

import * as React from "react";
import { Dialog as SheetPrimitive } from "@base-ui/react/dialog";
import { cva, type VariantProps } from "class-variance-authority";
import { Icon } from "@iconify/react";

import { cn } from "@/lib/utils";
import { buttonVariants } from "./button";
import { cardSlab, optionTrack } from "./_shared";

// Base UI accepts a state function for className; these wrappers merge it with
// cn(), so they take a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string };

/** Mallow Sheet root: a panel that slides in from one edge of the screen. */
const Sheet = SheetPrimitive.Root;

/** The control that opens the sheet. */
const SheetTrigger = SheetPrimitive.Trigger;

/** Closes the sheet when wrapped around a Cancel or Done button. */
const SheetClose = SheetPrimitive.Close;

/** Moves the sheet to the end of the document body. */
const SheetPortal = SheetPrimitive.Portal;

/** The soft plum scrim behind a sheet, fading in. */
const SheetOverlay = React.forwardRef<HTMLDivElement, WithClassName<SheetPrimitive.Backdrop.Props>>(
  ({ className, ...props }, ref) => (
    <SheetPrimitive.Backdrop
      ref={ref}
      data-slot="sheet-overlay"
      className={cn(
        "fixed inset-0 z-50 bg-(--scrim)",
        "transition-opacity duration-base ease-(--ease-out)",
        "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
        className,
      )}
      {...props}
    />
  ),
);
SheetOverlay.displayName = "SheetOverlay";

/** Sheet classes: the white card sliding in from its edge, its inner corners at a 1rem radius. */
const sheetVariants = cva(
  [
    "fixed z-50 flex flex-col gap-5 p-7 outline-none",
    cardSlab,
    "transition-[translate,opacity] duration-base ease-(--ease-out)",
    "data-[starting-style]:opacity-0 data-[ending-style]:opacity-0",
  ].join(" "),
  {
    variants: {
      side: {
        top: "inset-x-2 top-2 sm:inset-x-3 sm:top-3 max-h-5/6 rounded-3xl data-[starting-style]:-translate-y-[calc(100%+1rem)] data-[ending-style]:-translate-y-[calc(100%+1rem)]",
        bottom:
          "inset-x-2 bottom-2 sm:inset-x-3 sm:bottom-3 max-h-5/6 rounded-3xl data-[starting-style]:translate-y-[calc(100%+1rem)] data-[ending-style]:translate-y-[calc(100%+1rem)]",
        left: "inset-y-2 left-2 sm:inset-y-3 sm:left-3 h-auto w-3/4 max-w-sm rounded-3xl data-[starting-style]:-translate-x-[calc(100%+1rem)] data-[ending-style]:-translate-x-[calc(100%+1rem)]",
        right:
          "inset-y-2 right-2 sm:inset-y-3 sm:right-3 h-auto w-3/4 max-w-sm rounded-3xl data-[starting-style]:translate-x-[calc(100%+1rem)] data-[ending-style]:translate-x-[calc(100%+1rem)]",
      },
    },
    defaultVariants: {
      side: "right",
    },
  },
);

interface SheetContentProps
  extends WithClassName<SheetPrimitive.Popup.Props>,
    VariantProps<typeof sheetVariants> {}

/** Mallow sheet panel: the white card with a ghost close button, and a lilac grab handle on a bottom sheet. */
const SheetContent = React.forwardRef<HTMLDivElement, SheetContentProps>(
  ({ side = "right", className, children, ...props }, ref) => (
    <SheetPortal>
      <SheetOverlay />
      <SheetPrimitive.Popup
        ref={ref}
        data-slot="sheet-content"
        data-side={side}
        className={cn(sheetVariants({ side }), className)}
        {...props}
      >
        {side === "bottom" && (
          <div
            aria-hidden="true"
            data-slot="sheet-handle"
            className={cn("mx-auto -mt-3 h-1.5 w-12 shrink-0 rounded-full", optionTrack)}
          />
        )}
        {children}
        <SheetPrimitive.Close
          data-slot="sheet-close"
          className={cn(buttonVariants({ variant: "ghost", size: "icon-sm" }), "absolute end-4 top-4")}
        >
          <Icon icon="iconoir:xmark" className="size-4" aria-hidden="true" />
          <span className="sr-only">Close</span>
        </SheetPrimitive.Close>
      </SheetPrimitive.Popup>
    </SheetPortal>
  ),
);
SheetContent.displayName = "SheetContent";

/** The title block at the top of a sheet, leaving room for the close button. */
const SheetHeader = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div data-slot="sheet-header" className={cn("flex flex-col gap-1.5 pe-8 text-start", className)} {...props} />
);
SheetHeader.displayName = "SheetHeader";

/** The action row, pinned to the foot of the sheet. */
const SheetFooter = ({ className, ...props }: React.HTMLAttributes<HTMLDivElement>) => (
  <div
    data-slot="sheet-footer"
    className={cn("mt-auto flex flex-col-reverse gap-3 sm:flex-row sm:justify-end", className)}
    {...props}
  />
);
SheetFooter.displayName = "SheetFooter";

/** The sheet title in medium weight ink. */
const SheetTitle = React.forwardRef<HTMLHeadingElement, WithClassName<SheetPrimitive.Title.Props>>(
  ({ className, ...props }, ref) => (
    <SheetPrimitive.Title
      ref={ref}
      data-slot="sheet-title"
      className={cn("text-xl font-medium leading-tight tracking-tight text-foreground", className)}
      {...props}
    />
  ),
);
SheetTitle.displayName = "SheetTitle";

/** The supporting line under the title, in muted text. */
const SheetDescription = React.forwardRef<HTMLParagraphElement, WithClassName<SheetPrimitive.Description.Props>>(
  ({ className, ...props }, ref) => (
    <SheetPrimitive.Description
      ref={ref}
      data-slot="sheet-description"
      className={cn("text-sm leading-relaxed text-muted-foreground", className)}
      {...props}
    />
  ),
);
SheetDescription.displayName = "SheetDescription";

export {
  Sheet,
  SheetPortal,
  SheetOverlay,
  SheetTrigger,
  SheetClose,
  SheetContent,
  SheetHeader,
  SheetFooter,
  SheetTitle,
  SheetDescription,
};
